import{_ as i,C as a,o as l,c as u,j as d,a as e,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const q=JSON.parse('{"title":"菜单栏","description":"","frontmatter":{},"headers":[],"relativePath":"components/menubar.md","filePath":"components/menubar.md","lastUpdated":1787714572000}'),s={name:"components/menubar.md"},h={id:"菜单栏",tabindex:"-1"};function b(p,t,m,g,x,f){const n=a("Badge"),r=a("XhDemo");return l(),u("div",null,[d("h1",h,[t[0]||(t[0]=e("菜单栏 ",-1)),o(n,{type:"info",text:"menubar"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#菜单栏","aria-label":'Permalink to "菜单栏 <Badge type="info" text="menubar" />"'},"​",-1))]),t[3]||(t[3]=c('<p>一排入口各带一张菜单，同时只展开一张——桌面应用顶部那条。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>功能密集的编辑器类界面，命令多到需要按&quot;文件 / 编辑 / 视图&quot;分门别类。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>站点导航：那是<a href="./navigation-menu">导航菜单</a>或<a href="./side-nav">侧栏导航</a>。</li><li>只有一个入口：直接用<a href="./menu">菜单</a>。</li><li>移动端：这排入口在窄屏上放不下，且悬停切换无从谈起。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>value</code> 是当前展开的那一项，<code>null</code> 表示都收起。</li><li>一张菜单展开后，指针移到相邻入口即直接换张展开，不必先关再开。</li><li>禁用走 <code>aria-disabled</code> 而非原生 <code>disabled</code>：禁用的入口仍聚焦得上、仍是方向键的起点。</li><li><code>orientation</code> 竖排时上下键在入口之间走，左右键改为展开本项的菜单。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一排入口各带一张菜单，同时只展开一张；条目以 value 标识身份，禁用项方向键跳过也选不中</p>',10)),o(r,{src:"menubar/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[5]||(t[5]=d("p",null,"value 是当前展开的那一项，null 表示都收起；给了它就由宿主说了算",-1)),o(r,{src:"menubar/02-controlled"}),t[6]||(t[6]=d("h3",{id:"分组与标记位",tabindex:"-1"},[e("分组与标记位 "),d("a",{class:"header-anchor",href:"#分组与标记位","aria-label":'Permalink to "分组与标记位"'},"​")],-1)),t[7]||(t[7]=d("p",null,"group 用 value 跟自己的 group-label 配对，item-indicator 是纯装饰的勾选位",-1)),o(r,{src:"menubar/03-group"}),t[8]||(t[8]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[9]||(t[9]=d("p",null,"tone 换的是高亮底色，静止态一样：悬停到 trigger 上、或展开菜单后把焦点移到条目上才显现",-1)),o(r,{src:"menubar/04-tone"}),t[10]||(t[10]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[11]||(t[11]=d("p",null,"size 一档换掉 trigger 与菜单条目的字号与内边距，写在 root 上、浮层里的条目一并跟着变",-1)),o(r,{src:"menubar/05-size"}),t[12]||(t[12]=d("h3",{id:"竖排菜单栏",tabindex:"-1"},[e("竖排菜单栏 "),d("a",{class:"header-anchor",href:"#竖排菜单栏","aria-label":'Permalink to "竖排菜单栏"'},"​")],-1)),t[13]||(t[13]=d("p",null,"orientation 决定主轴：竖排时上下键在入口之间走，左右键改为展开本项的菜单",-1)),o(r,{src:"menubar/06-vertical"}),t[14]||(t[14]=d("h3",{id:"入口与条目的图标",tabindex:"-1"},[e("入口与条目的图标 "),d("a",{class:"header-anchor",href:"#入口与条目的图标","aria-label":'Permalink to "入口与条目的图标"'},"​")],-1)),t[15]||(t[15]=d("p",null,"图标是插槽里的普通节点：入口里排在文字前，条目里排在 item-text 前，逐项自己写",-1)),o(r,{src:"menubar/07-icon"}),t[16]||(t[16]=d("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[17]||(t[17]=d("p",null,"禁用走 aria-disabled 而非原生 disabled：禁用的入口仍聚焦得上、仍是方向键的起点，只是展不开菜单",-1)),o(r,{src:"menubar/08-disabled"}),t[18]||(t[18]=d("h3",{id:"装不下就收进「更多」",tabindex:"-1"},[e("装不下就收进「更多」 "),d("a",{class:"header-anchor",href:"#装不下就收进「更多」","aria-label":'Permalink to "装不下就收进「更多」"'},"​")],-1)),t[19]||(t[19]=d("p",null,"宿主自己观测容器宽度，一次收起一个入口直到这排不再溢出；收起来的那几张菜单在「更多」里各占一组",-1)),o(r,{src:"menubar/09-overflow"}),t[20]||(t[20]=d("h3",{id:"二级子菜单",tabindex:"-1"},[e("二级子菜单 "),d("a",{class:"header-anchor",href:"#二级子菜单","aria-label":'Permalink to "二级子菜单"'},"​")],-1)),t[21]||(t[21]=d("p",null,"XhMenubarSub 在菜单栏的一张菜单里再嵌一层：触发条目双重身份（菜单栏的方向键照常走、右方向键进子层），子层内用 XhMenu 系部件，选中带上所属菜单的身份汇到根并关掉整条菜单栏",-1)),o(r,{src:"menubar/10-submenu"}),t[22]||(t[22]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-menubar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMenubarContent</code> <code>XhMenubarGroup</code> <code>XhMenubarGroupLabel</code> <code>XhMenubarItem</code> <code>XhMenubarItemIndicator</code> <code>XhMenubarItemText</code> <code>XhMenubarPositioner</code> <code>XhMenubarRoot</code> <code>XhMenubarSeparator</code> <code>XhMenubarSub</code> <code>XhMenubarSubTrigger</code> <code>XhMenubarTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useMenubar</code></td></tr><tr><td>状态机</td><td><code>menubarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/menubar.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;menubar&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <strong><code>item</code></strong> · <code>item-text</code> · <code>item-indicator</code> · <code>separator</code> · <code>group</code> · <code>group-label</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>MenubarNode[]</code></td><td></td><td>菜单栏数据，显示文本与禁用的事实源。给了它，入口与条目部件只需报 value。 缺省即回到「文本与禁用逐个写在部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>当前展开项，给定即受控；null 表示都收起。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>菜单栏排布轴，默认 horizontal。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整条菜单栏禁用，展开与选中都不发生。</td></tr><tr><td><code>typeahead</code></td><td><code>boolean</code></td><td></td><td>菜单内的连打检索，默认开。</td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td></td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: MenubarValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化回调。</td></tr><tr><td><code>onSelect</code></td><td><code>(details: MenubarSelectDetails) =&gt; void</code></td><td></td><td>条目被选中；菜单随之收起。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>MenubarValueChangeDetails</code></td><td>展开项变化；detail 为 <code>{ value: string | null }</code></td></tr><tr><td><code>select</code></td><td><code>MenubarSelectDetails</code></td><td>条目被选中（菜单随之收起）；detail 为 <code>{ menu: string, value: string }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMenubarRoot</code></td><td><code>default</code></td><td><code>MenubarRootSlotProps</code></td><td></td></tr><tr><td><code>XhMenubarRoot</code></td><td><code>item</code></td><td><code>MenubarNodeMeta</code></td><td></td></tr><tr><td><code>XhMenubarSub</code></td><td><code>default</code></td><td><code>MenubarSubSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>open</code></p><p><strong>事件</strong>：<code>TRIGGER.TOGGLE</code> · <code>TRIGGER.OPEN</code> · <code>TRIGGER.POINTER</code> · <code>TRIGGER.FOCUS</code> · <code>CLOSE</code> · <code>MENUBAR.BLUR</code> · <code>VALUE.SET</code> · <code>ITEM.FOCUS</code> · <code>ITEM.LOST</code> · <code>ITEM.SELECT</code> · <code>SYNC.OPEN</code> · <code>SYNC.CLOSE</code></p><p><strong>判据</strong>：<code>hasValue</code> · <code>isCurrent</code> · <code>shouldAbsorbToggle</code> · <code>shouldSwitch</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useMenubar</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td>当前展开的那一项；都收起时为 null。</td></tr><tr><td><code>collection</code></td><td><code>readonly MenubarNodeMeta[]</code></td><td>collection 推出的入口元信息（各自带着它那张菜单的条目），按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td>有没有菜单展开着。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>trigger 的 roving 锚点；焦点不在菜单栏内时为 null。</td></tr><tr><td><code>focusedItem</code></td><td><code>string | null</code></td><td>展开菜单内持有焦点的条目；无锚点时为 null。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isOpen</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>(props: MenubarTriggerProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>(props: MenubarContentProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>(props: MenubarContentProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: MenubarItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: MenubarItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: MenubarItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupProps</code></td><td><code>(props: MenubarGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupLabelProps</code></td><td><code>(props: MenubarGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/menubar/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code></td><td>focus in trigger, horizontal</td><td>焦点移到下一个 trigger（禁用项跳过、尽头按 loop 回绕）；已有菜单展开着则展开项跟着切过去</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in trigger, horizontal</td><td>焦点移到上一个 trigger（禁用项跳过、尽头按 loop 回绕）；已有菜单展开着则展开项跟着切过去</td></tr><tr><td><code>Home</code></td><td>focus in trigger</td><td>焦点移到首个可用 trigger</td></tr><tr><td><code>End</code></td><td>focus in trigger</td><td>焦点移到末个可用 trigger</td></tr><tr><td><code>ArrowDown</code> / <code>Enter</code> / <code>Space</code></td><td>focus in trigger, horizontal</td><td>展开本项的菜单；方向键入口把焦点落到首个可用条目，Enter/Space 让焦点留在 trigger 上</td></tr><tr><td><code>ArrowUp</code></td><td>focus in trigger, horizontal</td><td>展开本项的菜单并把焦点落到末个可用条目</td></tr><tr><td><code>ArrowDown</code></td><td>open, focus in content</td><td>焦点移到下一个条目（禁用项跳过、尽头按 loop 回绕）</td></tr><tr><td><code>ArrowUp</code></td><td>open, focus in content</td><td>焦点移到上一个条目（禁用项跳过、尽头按 loop 回绕）</td></tr><tr><td><code>Home</code></td><td>open, focus in content</td><td>焦点移到本张菜单的首个可用条目</td></tr><tr><td><code>End</code></td><td>open, focus in content</td><td>焦点移到本张菜单的末个可用条目</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowLeft</code></td><td>open, focus in content</td><td>切到相邻菜单并保持展开，焦点落到那一项的 trigger 上</td></tr><tr><td><code>a-z</code> / <code>0-9</code></td><td>open, focus in content</td><td>连打检索：焦点跳到首字母匹配的条目（同字符连打则在候选间轮换）</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in item, not disabled</td><td>派发选中详情并收起菜单，焦点归还 trigger</td></tr><tr><td><code>Escape</code></td><td>open</td><td>收起菜单并把焦点留在 trigger 上</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open</td><td>收起菜单，焦点不被抢回 trigger，按 Tab 序列自然离开</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;menubar&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;menu&#39;</td></tr><tr><td><code>trigger</code></td><td><code>role</code></td><td>&#39;menuitem&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;menu&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;menuitem&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39;</td></tr><tr><td><code>separator</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr><tr><td><code>group</code></td><td><code>aria-labelledby</code></td><td><code>group-label</code> 部件的 id</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/menubar.css</code> 按部件选择：<code>[data-scope=&quot;menubar&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位 | undefined</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>content</code></td><td><code>data-instant</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位 | undefined</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-menubar-bg</code> · <code>--xh-menubar-border</code> · <code>--xh-menubar-content-gap</code> · <code>--xh-menubar-fg</code> · <code>--xh-menubar-group-gap</code> · <code>--xh-menubar-group-label-fg</code> · <code>--xh-menubar-group-label-font-size</code> · <code>--xh-menubar-group-label-font-weight</code> · <code>--xh-menubar-group-label-px</code> · <code>--xh-menubar-group-label-py</code> · <code>--xh-menubar-icon-size</code> · <code>--xh-menubar-item-active-font-weight</code> · <code>--xh-menubar-item-bg-active</code> · <code>--xh-menubar-item-bg-hover</code> · <code>--xh-menubar-item-fg</code> · <code>--xh-menubar-item-font-size</code> · <code>--xh-menubar-item-gap</code> · <code>--xh-menubar-item-indicator-fg</code> · <code>--xh-menubar-item-indicator-size</code> · <code>--xh-menubar-item-leading</code> · <code>--xh-menubar-item-px</code> · <code>--xh-menubar-item-py</code> · <code>--xh-menubar-item-radius</code> · <code>--xh-menubar-layer</code> · <code>--xh-menubar-max-h</code> · <code>--xh-menubar-max-w</code> · <code>--xh-menubar-min-w</code> · <code>--xh-menubar-px</code> · <code>--xh-menubar-py</code> · <code>--xh-menubar-radius</code> · <code>--xh-menubar-root-bg</code> · <code>--xh-menubar-root-fg</code> · <code>--xh-menubar-root-gap</code> · <code>--xh-menubar-root-px</code> · <code>--xh-menubar-root-py</code> · <code>--xh-menubar-root-radius</code> · <code>--xh-menubar-separator-color</code> · <code>--xh-menubar-separator-my</code> · <code>--xh-menubar-separator-thickness</code> · <code>--xh-menubar-shadow</code> · <code>--xh-menubar-trigger-bg-active</code> · <code>--xh-menubar-trigger-bg-hover</code> · <code>--xh-menubar-trigger-font-size</code> · <code>--xh-menubar-trigger-gap</code> · <code>--xh-menubar-trigger-px</code> · <code>--xh-menubar-trigger-py</code> · <code>--xh-menubar-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>装不下时由宿主观测容器宽度，一次收起一个入口到&quot;更多&quot;里，收起的菜单在&quot;更多&quot;中各占一组。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>入口名用单个名词，宽度尽量接近，避免展开时整排跳动。</li><li>常用命令在菜单里也标出快捷键，否则用户学不会绕开菜单栏。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>入口超过七八个：找一条命令比翻文档还慢。</li><li>在菜单栏里放选项而不是命令。</li></ul>',48))])}const T=i(s,[["render",b]]);export{q as __pageData,T as default};
